"""Shared wire types and bounded metadata validation for the campaign tools."""
import base64
import binascii
import ipaddress
import json
import re

DOC = ipaddress.IPv6Network('2001:db8::/32')
ID = re.compile(r'[A-Za-z0-9_-]{1,24}\Z')
COLUMNS = ('type', 'id', 'revision', 'published', 'op', 'lease', 'event',
           'probe', 'target', 'responder', 'result', 'service', 'attempt',
           'payload')
MAX_TIME = 10 ** 12
MAX_INPUT = 64 * 1024 ** 2
MAX_DECODED = 32 * 1024 ** 2
MAX_DECOMPRESSED = 128 * 1024 ** 2
MAX_FIELD_BYTES = 131072
MAX_RECORDS = 200000
MAX_WINDOW = 128 * 1024 ** 2


class Invalid(ValueError):
    pass


class CaptureError(ValueError):
    pass


def need(condition):
    if not condition:
        raise Invalid('invalid metadata')


def ident(value):
    return isinstance(value, str) and ID.fullmatch(value) is not None


def integer(value, low=0, high=MAX_TIME):
    return type(value) is int and low <= value <= high


def fields(value, names):
    return type(value) is dict and set(value) == set(names.split())


def address(text):
    need(isinstance(text, str) and len(text) <= 64 and '%' not in text
         and not any(c.isspace() for c in text))
    try:
        value = ipaddress.IPv6Address(text)
    except ValueError:
        raise Invalid('invalid IPv6 address') from None
    need(value in DOC)
    return int(value)


def prefix(text, lengths=None):
    need(isinstance(text, str) and len(text) <= 80 and '%' not in text
         and not any(c.isspace() for c in text))
    try:
        value = ipaddress.IPv6Network(text, strict=True)
    except ValueError:
        raise Invalid('invalid IPv6 prefix') from None
    need(value.version == 6 and value.subnet_of(DOC)
         and (lengths is None or value.prefixlen in lengths))
    return value


def addresses(values):
    return [str(ipaddress.IPv6Address(n)) for n in sorted(values)]


def decimal(text, high=MAX_TIME):
    need(isinstance(text, str) and 1 <= len(text) <= 16
         and text.isascii() and text.isdecimal())
    n = int(text)
    need(n <= high)
    return n


def decode64(text, error=Invalid):
    if not isinstance(text, str):
        raise error('invalid base64')
    try:
        return base64.b64decode(text.encode('ascii'), validate=True)
    except (ValueError, UnicodeError, binascii.Error):
        raise error('invalid base64') from None


def unique(pairs):
    result = {}
    for key, value in pairs:
        need(key not in result)
        result[key] = value
    return result


def parse_json(data):
    def reject_constant(_):
        raise Invalid('nonfinite JSON number')

    try:
        return json.loads(data.decode('utf-8'), object_pairs_hook=unique,
                          parse_constant=reject_constant)
    except (ValueError, UnicodeError, RecursionError):
        raise Invalid('invalid JSON') from None


def forest(items):
    need(type(items) is list and len(items) <= 4096)
    nodes = {}
    for row in items:
        need(fields(row, 'id parent capacity') and ident(row['id']))
        need(row['id'] not in nodes and integer(row['capacity'], 0, 4096))
        need(row['parent'] is None or ident(row['parent']))
        nodes[row['id']] = dict(row)
    paths = {}
    for node in nodes:
        seen = []
        at = node
        while at is not None:
            need(at in nodes and at not in seen and len(seen) < 32)
            seen.append(at)
            at = nodes[at]['parent']
        paths[node] = tuple(seen)
    return nodes, paths


def validate(job):
    need(fields(job, 'version seed leases services queries captures requests '
                     'offers request_quotas offer_quotas'))
    need(type(job['version']) is int and job['version'] == 3
         and ident(job['seed']))

    queries = job['queries']
    need(type(queries) is list and 1 <= len(queries) <= 4)
    need(all(integer(q) for q in queries) and len(set(queries)) == len(queries))

    services = {}
    need(type(job['services']) is list and len(job['services']) <= 8)
    for row in job['services']:
        need(fields(row, 'id kind') and ident(row['id'])
             and row['id'] not in services)
        need(row['kind'] in ('tcp', 'adb', 'sync'))
        services[row['id']] = row['kind']

    leases = {}
    target_count = 0
    need(type(job['leases']) is list and len(job['leases']) <= 2048)
    for row in job['leases']:
        need(fields(row, 'id prefix start end subnets low_count'))
        need(ident(row['id']) and row['id'] not in leases)
        need(integer(row['start']) and integer(row['end'], 1, MAX_TIME + 1)
             and row['start'] < row['end'])
        net = prefix(row['prefix'], (56, 64))
        subs = row['subnets']
        need(type(subs) is list and 1 <= len(subs) <= 16)
        need(all(integer(s, 0, 255 if net.prefixlen == 56 else 0)
                 for s in subs) and len(set(subs)) == len(subs))
        need(integer(row['low_count'], 1, 32))
        target_count += len(subs) * (row['low_count'] + 1)
        leases[row['id']] = {**row, 'network': net, 'subnets': sorted(subs)}
    need(target_count <= 65536)

    captures = job['captures']
    need(type(captures) is list and len(captures) <= 16)
    nchunks = 0
    for capture in captures:
        need(fields(capture, 'encoding chunks')
             and capture['encoding'] in ('csv', 'zstd'))
        need(type(capture['chunks']) is list
             and all(isinstance(x, str) for x in capture['chunks']))
        nchunks += len(capture['chunks'])
    need(nchunks <= 1024)

    rq, rpaths = forest(job['request_quotas'])
    oq, opaths = forest(job['offer_quotas'])

    requests = {}
    need(type(job['requests']) is list and len(job['requests']) <= 4096)
    for row in job['requests']:
        need(fields(row, 'id at lease target service group'))
        need(ident(row['id']) and row['id'] not in requests)
        need(integer(row['at']) and row['at'] in queries
             and row['lease'] in leases and row['service'] in services
             and row['group'] in rq)
        requests[row['id']] = {**row, 'address': address(row['target'])}

    offers = {}
    pairs = 0
    need(type(job['offers']) is list and len(job['offers']) <= 8192)
    for row in job['offers']:
        need(fields(row, 'id time service prefix capacity cost group requests'))
        need(ident(row['id']) and row['id'] not in offers)
        need(integer(row['time']) and row['service'] in services)
        net = prefix(row['prefix'])
        need(net.prefixlen >= 32 and integer(row['capacity'], 0, 4096)
             and integer(row['cost'], 0, 10 ** 9) and row['group'] in oq
             and type(row['requests']) is list)
        need(all(isinstance(x, str) and x in requests for x in row['requests']))
        need(len(set(row['requests'])) == len(row['requests']))
        pairs += len(row['requests'])
        offers[row['id']] = {**row, 'network': net}
    need(pairs <= 262144)

    return {'seed': job['seed'], 'leases': leases, 'services': services,
            'queries': sorted(queries), 'captures': captures,
            'requests': requests, 'offers': offers,
            'request_quotas': rq, 'request_paths': rpaths,
            'offer_quotas': oq, 'offer_paths': opaths}
PY
